    @Override
    public boolean equals(Object other) {
        if (this == other) return true;
        if (!(other instanceof Reply reply)) return false;
        return exitCode == reply.exitCode
                && started == reply.started
                && uncertain == reply.uncertain
                && Arrays.equals(stdout, reply.stdout)
                && Arrays.equals(stderr, reply.stderr);
