private static String jsonEscape(String value) {
    var sb = new StringBuilder(value.length() + 8);
    for (char c : value.toCharArray()) {
        switch (c) {
            case '"' -> sb.append("\\\"");
            case '\\' -> sb.append("\\\\");
            default -> {
                if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                else sb.append(c);
            }
        }
    }
    return sb.toString();
}

